"""Deterministic bisect controller with `git bisect skip` semantics (PRD §8.1).

The controller knows nothing about evals: it asks `classify(sha)` for GOOD, BAD or SKIP and
narrows the range. `good` is implicitly GOOD and the last candidate (`bad`) is implicitly BAD.
"""

from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass, field
from enum import StrEnum


class Verdict(StrEnum):
    GOOD = "GOOD"
    BAD = "BAD"
    SKIP = "SKIP"


@dataclass
class BisectResult:
    first_bad: str | None
    """The culprit when the boundary is exact; None when skipped commits make it ambiguous."""
    suspects: list[str]
    """Commits that may contain the culprit, oldest first (one entry when exact)."""
    tested: list[tuple[str, Verdict]] = field(default_factory=list)


def probe_order(lo: int, hi: int) -> list[int]:
    """Indices strictly between lo and hi, midpoint first, then alternating right/left."""
    mid = (lo + hi) // 2
    order = [mid]
    for step in range(1, hi - lo):
        for idx in (mid + step, mid - step):
            if lo < idx < hi:
                order.append(idx)
    return order


def bisect(candidates: list[str], classify: Callable[[str], Verdict]) -> BisectResult:
    """`candidates` is `git rev-list --first-parent --reverse good..bad`, so the last one is `bad`."""
    if not candidates:
        raise ValueError("empty commit range: good and bad are the same commit")
    lo, hi = -1, len(candidates) - 1
    skipped: set[int] = set()
    tested: list[tuple[str, Verdict]] = []
    while hi - lo > 1:
        untested = [i for i in probe_order(lo, hi) if i not in skipped]
        if not untested:
            break
        idx = untested[0]
        verdict = classify(candidates[idx])
        tested.append((candidates[idx], verdict))
        if verdict is Verdict.GOOD:
            lo = idx
        elif verdict is Verdict.BAD:
            hi = idx
        else:
            skipped.add(idx)
    suspects = candidates[lo + 1 : hi + 1]
    return BisectResult(first_bad=suspects[0] if len(suspects) == 1 else None, suspects=suspects, tested=tested)

"""Commit intent from Entire (`entire checkpoint explain <sha>`), with leakage filter and fallback.

Only the context of the commit under examination is fetched, never its neighbours. Before any
Entire text reaches an LLM, lines that could leak benchmark labels are stripped and counted.
"""

from __future__ import annotations

import re
import subprocess
from dataclasses import dataclass
from pathlib import Path

from culprit.gitops import diff, git, message

ANSI = re.compile(r"\x1b\[[0-9;?]*[A-Za-z]")
LEAK_PATTERNS = [
    r"hist/",
    r"scenario",
    r"\bR[1-6]\b",
    r"culprit",
    r"regression",
    r"seed",
    r"gap",
    r"pause",
]
# The default branch names carry no benchmark information and appear in ordinary prose.
HARMLESS_REFS = {"HEAD", "main", "master", "origin", "origin/HEAD", "origin/main", "origin/master"}


@dataclass(frozen=True)
class Intent:
    available: bool
    checkpoint_id: str | None
    text: str
    lines_removed: int
    source: str  # "entire" or "fallback: <reason>"


def ref_names(repo: Path) -> list[str]:
    out = git(repo, "for-each-ref", "--format=%(refname:short)", "refs/heads", "refs/tags", "refs/remotes")
    return sorted({r for r in out.splitlines() if r and r not in HARMLESS_REFS})


def leak_filter(text: str, refs: list[str]) -> tuple[str, int]:
    patterns = [re.compile(p, re.IGNORECASE) if not p.startswith(r"\bR") else re.compile(p) for p in LEAK_PATTERNS]
    patterns += [re.compile(rf"(?<![\w/.-]){re.escape(r)}(?![\w/-])") for r in refs]
    kept, removed = [], 0
    for line in text.splitlines():
        if any(p.search(line) for p in patterns):
            removed += 1
        else:
            kept.append(line)
    return "\n".join(kept), removed


def explain(repo: Path, sha: str, timeout_s: int = 120) -> tuple[int, str]:
    proc = subprocess.run(
        ["entire", "checkpoint", "explain", sha, "--no-pager"],
        cwd=repo, capture_output=True, text=True, timeout=timeout_s,
    )
    return proc.returncode, ANSI.sub("", proc.stdout + proc.stderr)


def commit_intent(repo: Path, sha: str) -> Intent:
    refs = ref_names(repo)
    try:
        code, out = explain(repo, sha)
    except (OSError, subprocess.TimeoutExpired) as exc:
        code, out = -1, f"entire unavailable: {exc}"
    match = re.search(r"Checkpoint\s+([0-9A-Z]{20,})", out)
    if code == 0 and match:
        text, removed = leak_filter(out, refs)
        return Intent(True, match.group(1), text, removed, "entire")
    reason = out.strip().splitlines()[0] if out.strip() else f"exit {code}"
    fallback = f"Commit message:\n{message(repo, sha)}\n\nDiff:\n{diff(repo, sha)}"
    text, removed = leak_filter(fallback, refs)
    return Intent(False, None, text, removed, f"fallback: {reason}")

